using Contoso.Orders;

namespace Contoso.Orders.Tests;

[TestClass]
public sealed class OrderServiceTests
{
    private readonly OrderService _service;

    public OrderServiceTests()
    {
        _service = new OrderService();
    }

    private static List<OrderItem> CreateItems(params (string name, decimal price, int qty)[] items) =>
        items.Select(i => new OrderItem { ProductName = i.name, Price = i.price, Quantity = i.qty }).ToList();

    [TestMethod]
    public void CreateOrder_WithValidItems_ReturnsOrderWithCorrectTotal()
    {
        // Arrange
        var items = CreateItems(("Widget", 10.00m, 2), ("Gadget", 25.00m, 1));

        // Act
        var order = _service.CreateOrder("customer-1", items);

        // Assert
        Assert.AreEqual("customer-1", order.CustomerId);
        Assert.AreEqual(45.00m, order.Total);
        Assert.HasCount(2, order.Items);
        Assert.IsNotNull(order.Id);
    }

    [TestMethod]
    public void CreateOrder_WithSingleItem_CalculatesTotalCorrectly()
    {
        // Arrange
        var items = CreateItems(("Widget", 15.50m, 3));

        // Act
        var order = _service.CreateOrder("customer-2", items);

        // Assert
        Assert.AreEqual(46.50m, order.Total);
        Assert.ContainsSingle(order.Items);
    }

    [TestMethod]
    public void CreateOrder_WithNullCustomerId_ThrowsArgumentNullException()
    {
        // Arrange
        var items = CreateItems(("Widget", 10.00m, 1));

        // Act & Assert
        var ex = Assert.ThrowsExactly<ArgumentNullException>(() => _service.CreateOrder(null!, items));
        Assert.AreEqual("customerId", ex.ParamName);
    }

    [TestMethod]
    public void CreateOrder_WithNullItems_ThrowsArgumentNullException()
    {
        // Act & Assert
        var ex = Assert.ThrowsExactly<ArgumentNullException>(() => _service.CreateOrder("customer-1", null!));
        Assert.AreEqual("items", ex.ParamName);
    }

    [TestMethod]
    public void CreateOrder_WithEmptyItems_ThrowsInvalidOperationException()
    {
        // Act & Assert
        var ex = Assert.ThrowsExactly<InvalidOperationException>(
            () => _service.CreateOrder("customer-1", []));
        Assert.AreEqual("Cannot create an order with no items.", ex.Message);
    }

    [TestMethod]
    public void CreateOrder_SetsCreatedAtToRecentTime()
    {
        // Arrange
        var items = CreateItems(("Widget", 5.00m, 1));
        var before = DateTime.UtcNow;

        // Act
        var order = _service.CreateOrder("customer-1", items);

        // Assert
        var after = DateTime.UtcNow;
        Assert.IsTrue(order.CreatedAt >= before && order.CreatedAt <= after);
    }

    [TestMethod]
    public void GetOrder_WithExistingId_ReturnsOrder()
    {
        // Arrange
        var items = CreateItems(("Widget", 10.00m, 1));
        var created = _service.CreateOrder("customer-1", items);

        // Act
        var retrieved = _service.GetOrder(created.Id);

        // Assert
        Assert.IsNotNull(retrieved);
        Assert.AreSame(created, retrieved);
    }

    [TestMethod]
    public void GetOrder_WithNonExistentId_ReturnsNull()
    {
        // Act
        var result = _service.GetOrder("non-existent-id");

        // Assert
        Assert.IsNull(result);
    }

    [TestMethod]
    public void GetOrdersByCustomer_WithMultipleOrders_ReturnsAllMatchingOrders()
    {
        // Arrange
        var items = CreateItems(("Widget", 10.00m, 1));
        _service.CreateOrder("customer-A", items);
        _service.CreateOrder("customer-A", items);
        _service.CreateOrder("customer-B", items);

        // Act
        var orders = _service.GetOrdersByCustomer("customer-A");

        // Assert
        Assert.HasCount(2, orders);
    }

    [TestMethod]
    public void GetOrdersByCustomer_WithNoOrders_ReturnsEmptyList()
    {
        // Act
        var orders = _service.GetOrdersByCustomer("no-orders-customer");

        // Assert
        Assert.IsEmpty(orders);
    }

    [TestMethod]
    [DataRow(1, 10.00, 10.00, DisplayName = "Single item")]
    [DataRow(5, 3.50, 17.50, DisplayName = "Multiple quantity")]
    [DataRow(1, 0.01, 0.01, DisplayName = "Minimum price")]
    public void CreateOrder_CalculatesTotal_ForVariousQuantities(int qty, double price, double expectedTotal)
    {
        // Arrange
        var items = CreateItems(("Item", (decimal)price, qty));

        // Act
        var order = _service.CreateOrder("customer-1", items);

        // Assert
        Assert.AreEqual((decimal)expectedTotal, order.Total);
    }
}

